package stack_test

import (
	"testing"

	"github.com/ai-verification/go-stack/internal/stack"
)

func TestPushAndPop(t *testing.T) {
	s := stack.New()
	s.Push(1)
	s.Push(2)
	s.Push(3)
	v, ok := s.Pop()
	if !ok || v != 3 {
		t.Fatalf("expected 3, got %v ok=%v", v, ok)
	}
	v, ok = s.Pop()
	if !ok || v != 2 {
		t.Fatalf("expected 2, got %v ok=%v", v, ok)
	}
}

func TestPopEmpty(t *testing.T) {
	s := stack.New()
	_, ok := s.Pop()
	if ok {
		t.Fatal("expected false on empty stack")
	}
}

func TestPeek(t *testing.T) {
	s := stack.New()
	s.Push("hello")
	v, ok := s.Peek()
	if !ok || v != "hello" {
		t.Fatalf("expected hello, got %v ok=%v", v, ok)
	}
	if s.Len() != 1 {
		t.Fatal("Peek should not remove element")
	}
}

func TestPeekEmpty(t *testing.T) {
	s := stack.New()
	_, ok := s.Peek()
	if ok {
		t.Fatal("expected false on empty stack peek")
	}
}

func TestLenAndIsEmpty(t *testing.T) {
	s := stack.New()
	if !s.IsEmpty() {
		t.Fatal("expected empty")
	}
	s.Push(42)
	if s.Len() != 1 {
		t.Fatalf("expected len=1, got %d", s.Len())
	}
	if s.IsEmpty() {
		t.Fatal("expected not empty")
	}
}

func TestMixedTypes(t *testing.T) {
	s := stack.New()
	s.Push(1)
	s.Push("two")
	s.Push(3.0)
	v, _ := s.Pop()
	if v != 3.0 {
		t.Fatalf("expected 3.0, got %v", v)
	}
}
